  1→//! Layer Subscribe Protocol (pull-based via __sync_meta)
  2→//!
  3→//! Handles the pull-based layer discovery and subscription flow:
  4→//! 1. Peer detects new entries in their __sync_meta (via SyncOffer)
  5→//! 2. Peer sends LayerSubscribe for each unsynced layer (with consent permit)
  6→//! 3. Responder validates, exports snapshot, issues permit, responds with LayerSubscribeAck
  7→//! 4. Subscriber decrypts data, stores permit, applies to Scribe, marks synced
  8→
  9→use tracing::{debug, error, info, warn, instrument};
 10→
 11→use crate::message::*;
 12→use transport::Connection;
 13→
 14→use super::guards::require_auth;
 15→use super::{PeerActor, PeerActorState};
 16→use butler::ScribeMessage;
 17→
 18→/// Default layer consent template — subscriber consents to receive layer sync updates
 19→const DEFAULT_LAYER_CONSENT_TEMPLATE: &str = r#"{
 20→  "consent_template": {
 21→    "token_type": "sync_layer_consent",
 22→    "operations": { "receive_updates": "allow" },
 23→    "auth_capabilities": { "accept_sync": true },
 24→    "relationship": "sync_consent"
 25→  }
 26→}"#;
 27→
 28→impl<C: Connection> PeerActor<C> {
 29→
 30→    /// Issue a layer consent permit for a specific layer
 31→    ///
 32→    /// **Context**: Subscriber is about to send LayerSubscribe, needs consent permit
 33→    /// **Returns**: consent_permit token, or empty string on failure
 34→    async fn issue_layer_consent(
 35→        &self,
 36→        page_id: &str,
 37→        layer_name: &str,
 38→        state: &PeerActorState<C>,
 39→    ) -> String {
 40→        let (peer_did, _) = match require_auth(&state.state) {
 41→            Ok(info) => (info.0.to_string(), info.1.to_string()),
 42→            Err(_) => return String::new(),
 43→        };
 44→
 45→        let signing_key = match state.butler.signing_key().await {
 46→            Ok(key) => key,
 47→            Err(e) => {
 48→                warn!("Failed to get signing key for layer consent: {}", e);
 49→                return String::new();
 50→            }
 51→        };
 52→
 53→        // Get page permit as proof for consent
 54→        let page_permit = match state.butler.pages().get(page_id) {
 55→            Ok(Some(data)) => match data.get_permit() {
 56→                Some(permit) => permit.clone(),
 57→                None => {
 58→                    warn!("No page permit for page={}, sending consent without proof", page_id);
 59→                    return String::new();
 60→                }
 61→            },
 62→            _ => {
 63→                warn!("Failed to get page data for consent: page={}", page_id);
 64→                return String::new();
 65→            }
 66→        };
 67→
 68→        let full_layer_name = format!("{}/{}", page_id, layer_name);
 69→        match gurkha::issue_sync_layer_consent(
 70→            &signing_key,
 71→            &peer_did,
 72→            page_id,
 73→            &full_layer_name,
 74→            &page_permit,
 75→            DEFAULT_LAYER_CONSENT_TEMPLATE,
 76→        ).await {
 77→            Ok((token, _cid)) => {
 78→                debug!("Issued layer consent for layer={}", layer_name);
 79→                token
 80→            }
 81→            Err(e) => {
 82→                warn!("Failed to issue layer consent: {}", e);
 83→                String::new()
 84→            }
 85→        }
 86→    }
 87→
 88→    /// Subscribe to dynamic layers on a peer (triggered by Coordinator)
 89→    ///
 90→    /// **Context**: Scribe emitted SyncEvent::SubscribeLayers, Coordinator forwarded here
 91→    /// **We do**: Issue consent permits, send LayerSubscribe for each layer
 92→    #[instrument(skip(self, state), fields(node = %self.node_id, page_id = %page_id))]
 93→    pub(in crate::peer_actor) async fn subscribe_to_layers(
 94→        &self,
 95→        page_id: &str,
 96→        layers: &[String],
 97→        state: &mut PeerActorState<C>,
 98→    ) {
 99→        if layers.is_empty() {
100→            return;
101→        }
102→
103→        info!(
104→            page_id = %page_id,
105→            count = layers.len(),
106→            "Subscribing to {} layers via LayerSubscribe",
107→            layers.len()
108→        );
109→
110→        for layer_name in layers {
111→            let consent_permit = self.issue_layer_consent(page_id, layer_name, state).await;
112→            let request_id = uuid::Uuid::new_v4().to_string();
113→            let msg = Message::LayerSubscribe(LayerSubscribeMsg {
114→                request_id,
115→                page_id: page_id.to_string(),
116→                layer_name: layer_name.clone(),
117→                consent_permit,
118→            });
119→            self.send_message(&msg, state).await;
120→            debug!(page_id = %page_id, layer = %layer_name, "Sent LayerSubscribe");
121→        }
122→    }
123→
124→    /// Detect __sync_meta updates and send LayerSubscribe for unsynced entries
125→    ///
126→    /// **Context**: PeerActor applied a SyncOffer for a __sync_meta layer
127→    /// **We do**: Query Scribe for unsynced entries, issue consent, send LayerSubscribe for each
128→    #[instrument(skip(self, state), fields(node = %self.node_id, page_id = %page_id))]
129→    pub(in crate::peer_actor) async fn check_sync_meta_and_subscribe(
130→        &self,
131→        page_id: &str,
132→        state: &mut PeerActorState<C>,
133→    ) {
134→        let scribe = match state.butler.open_page(page_id).await {
135→            Ok(s) => s,
136→            Err(e) => {
137→                error!("Failed to open page {} for sync_meta check: {}", page_id, e);
138→                return;
139→            }
140→        };
141→
142→        // Query Scribe for unsynced __sync_meta entries
143→        let (reply_tx, reply_rx) = tokio::sync::oneshot::channel();
144→        if let Err(e) = scribe.cast(ScribeMessage::GetUnsyncedSyncMeta { reply: reply_tx }) {
145→            error!("Failed to query unsynced sync_meta: {}", e);
146→            return;
147→        }
148→
149→        let unsynced = match reply_rx.await {
150→            Ok(entries) => entries,
151→            Err(_) => {
152→                error!("GetUnsyncedSyncMeta reply channel dropped");
153→                return;
154→            }
155→        };
156→
157→        if unsynced.is_empty() {
158→            debug!("No unsynced __sync_meta entries for page={}", page_id);
159→            return;
160→        }
161→
162→        // Delegate to subscribe_to_layers which handles consent + sending
163→        self.subscribe_to_layers(page_id, &unsynced, state).await;
164→    }
165→
166→    /// Handle incoming LayerSubscribe from peer
167→    ///
168→    /// **Context**: Peer discovered a layer in __sync_meta, requests data + permit
169→    /// **We do**: Store consent permit, delegate to Scribe for permit + snapshot, encrypt, respond
170→    #[instrument(skip(self, state, consent_permit), fields(page_id = %page_id, layer = %layer_name))]
171→    pub(in crate::peer_actor) async fn on_layer_subscribe(
172→        &self,
173→        request_id: &str,
174→        page_id: &str,
175→        layer_name: &str,
176→        consent_permit: &str,
177→        state: &mut PeerActorState<C>,
178→    ) {
179→        let (peer_did, _) = match require_auth(&state.state) {
180→            Ok(info) => (info.0.to_string(), info.1.to_string()),
181→            Err(_) => {
182→                warn!("LayerSubscribe from unauthenticated peer: {}", self.node_id);
183→                return;
184→            }
185→        };
186→
187→        info!(
188→            "LayerSubscribe: page={} layer={} from peer={}",
189→            page_id, layer_name, peer_did
190→        );
191→
192→        // Store consent permit if provided
193→        if !consent_permit.is_empty() {
194→            let full_layer_name = format!("{}/{}", page_id, layer_name);
195→            if let Err(e) = state.butler.permits().store_viewer_layer_consent(
196→                &peer_did, page_id, &full_layer_name, consent_permit,
197→            ) {
198→                warn!("Failed to store viewer layer consent: {}", e);
199→                // Non-fatal — continue processing
200→            } else {
201→                debug!("Stored viewer layer consent for peer={} layer={}", peer_did, layer_name);
202→            }
203→        }
204→
205→        // Get Scribe for this page
206→        let scribe = match state.page_subscriptions.get(page_id) {
207→            Some(sub) => sub.scribe.clone(),
208→            None => {
209→                warn!("LayerSubscribe: no page subscription for page={}", page_id);
210→                self.send_layer_subscribe_reject(request_id, page_id, layer_name, "page not subscribed", state).await;
211→                return;
212→            }
213→        };
214→
215→        // Delegate to Scribe: issues permit, adds subscriber, exports snapshot
216→        let (reply_tx, reply_rx) = tokio::sync::oneshot::channel();
217→        if let Err(e) = scribe.cast(ScribeMessage::HandleLayerSubscribe {
218→            layer_name: layer_name.to_string(),
219→            peer_did: peer_did.clone(),
220→            reply: reply_tx,
221→        }) {
222→            error!("Failed to send HandleLayerSubscribe to Scribe: {}", e);
223→            self.send_layer_subscribe_reject(request_id, page_id, layer_name, "internal error", state).await;
224→            return;
225→        }
226→
227→        let (snapshot_data, state_vector, layer_permit) = match reply_rx.await {
228→            Ok(Ok(result)) => result,
229→            Ok(Err(e)) => {
230→                warn!("HandleLayerSubscribe error for layer={}: {}", layer_name, e);
231→                self.send_layer_subscribe_reject(request_id, page_id, layer_name, &e, state).await;
232→                return;
233→            }
234→            Err(_) => {
235→                error!("HandleLayerSubscribe reply dropped for layer={}", layer_name);
236→                self.send_layer_subscribe_reject(request_id, page_id, layer_name, "internal error", state).await;
237→                return;
238→            }
239→        };
240→
241→        // Encrypt snapshot for transfer
242→        let peer_encryption_key = match state.peer_encryption_key {
243→            Some(key) => key,
244→            None => {
245→                warn!("Cannot send LayerSubscribeAck: peer encryption key not set");
246→                self.send_layer_subscribe_reject(request_id, page_id, layer_name, "no encryption key", state).await;
247→                return;
248→            }
249→        };
250→
251→        let (ephemeral_public, encrypted_data) = match herald::encrypt_for_transfer(
252→            &peer_encryption_key,
253→            &snapshot_data,
254→        ) {
255→            Ok(result) => result,
256→            Err(e) => {
257→                error!("Failed to encrypt LayerSubscribeAck data: {}", e);
258→                self.send_layer_subscribe_reject(request_id, page_id, layer_name, "encryption failed", state).await;
259→                return;
260→            }
261→        };
262→
263→        // Ensure peer is a per-layer subscriber for future broadcasts.
264→        // HandleLayerSubscribe attempts this internally, but as a belt-and-suspenders
265→        // we also send an explicit AuthorizeLayerSubscriber from here.
266→        scribe.cast(ScribeMessage::AuthorizeLayerSubscriber {
267→            layer_name: layer_name.to_string(),
268→            subscriber_did: peer_did.clone(),
269→        }).ok();
270→
271→        // Mark the entry as synced in the peer's __sync_meta on the node
272→        if let Some(sub) = state.page_subscriptions.get(page_id) {
273→            let meta_layer = format!("__sync_meta:{}", peer_did);
274→            let _ = sub.scribe.cast(ScribeMessage::UpdateFromJson {
275→                layer_name: meta_layer,
276→                path: layer_name.to_string(),
277→                value: serde_json::json!(true),
278→                reply: None,
279→            });
280→        }
281→
282→        let msg = Message::LayerSubscribeAck(LayerSubscribeAckMsg {
283→            request_id: request_id.to_string(),
284→            page_id: page_id.to_string(),
285→            layer_name: layer_name.to_string(),
286→            accepted: true,
287→            reason: None,
288→            data: encrypted_data,
289→            state_vector,
290→            ephemeral_public,
291→            layer_permit,
292→        });
293→
294→        self.send_message(&msg, state).await;
295→        info!("Sent LayerSubscribeAck for page={} layer={} to peer={}", page_id, layer_name, peer_did);
296→    }
297→
298→    /// Send a rejected LayerSubscribeAck
299→    async fn send_layer_subscribe_reject(
300→        &self,
301→        request_id: &str,
302→        page_id: &str,
303→        layer_name: &str,
304→        reason: &str,
305→        state: &PeerActorState<C>,
306→    ) {
307→        let msg = Message::LayerSubscribeAck(LayerSubscribeAckMsg {
308→            request_id: request_id.to_string(),
309→            page_id: page_id.to_string(),
310→            layer_name: layer_name.to_string(),
311→            accepted: false,
312→            reason: Some(reason.to_string()),
313→            data: Vec::new(),
314→            state_vector: Vec::new(),
315→            ephemeral_public: [0u8; 32],
316→            layer_permit: String::new(),
317→        });
318→        self.send_message(&msg, state).await;
319→    }
320→
321→    /// Handle incoming LayerSubscribeAck from peer
322→    ///
323→    /// **Context**: Peer processed our LayerSubscribe, sent data + permit
324→    /// **Permit-driven**: Detects permit type to determine handling:
325→    ///   - `layer_authority` → We're the node, creator sent authority. Store + fan out.
326→    ///   - `layer_permit` → We're the user, node sent access permit. Store + apply.
327→    #[instrument(skip(self, state, data, state_vector, ephemeral_public, layer_permit), fields(page_id = %page_id, layer = %layer_name))]
328→    pub(in crate::peer_actor) async fn on_layer_subscribe_ack(
329→        &self,
330→        _request_id: &str,
331→        page_id: &str,
332→        layer_name: &str,
333→        accepted: bool,
334→        reason: Option<&str>,
335→        data: &[u8],
336→        state_vector: &[u8],
337→        ephemeral_public: &[u8; 32],
338→        layer_permit: &str,
339→        state: &mut PeerActorState<C>,
340→    ) {
341→        let (peer_did, _) = match require_auth(&state.state) {
342→            Ok(info) => (info.0.to_string(), info.1.to_string()),
343→            Err(_) => {
344→                warn!("LayerSubscribeAck from unauthenticated peer: {}", self.node_id);
345→                return;
346→            }
347→        };
348→
349→        if !accepted {
350→            warn!(
351→                "LayerSubscribeAck rejected for page={} layer={}: {}",
352→                page_id, layer_name, reason.unwrap_or("unknown")
353→            );
354→            return;
355→        }
356→
357→        info!(
358→            "LayerSubscribeAck: page={} layer={} from peer={} data_len={}",
359→            page_id, layer_name, peer_did, data.len()
360→        );
361→
362→        // Decrypt data
363→        let our_secret = match state.butler.encryption_key().await {
364→            Ok(key) => key,
365→            Err(e) => {
366→                error!("Failed to get encryption key for LayerSubscribeAck: {}", e);
367→                return;
368→            }
369→        };
370→
371→        let decrypted_data = match herald::decrypt_from_transfer(&our_secret, ephemeral_public, data) {
372→            Ok(plaintext) => plaintext,
373→            Err(e) => {
374→                error!("Failed to decrypt LayerSubscribeAck data: {}", e);
375→                return;
376→            }
377→        };
378→
379→        // Detect permit type to determine handling path
380→        let is_authority = gurkha::Permit::from_token(layer_permit)
381→            .ok()
382→            .and_then(|p| p.get_fact("token_type").cloned())
383→            .and_then(|v| v.as_str().map(|s| s.to_string()))
384→            .map(|t| t == "layer_authority")
385→            .unwrap_or(false);
386→
387→        if is_authority {
388→            self.handle_authority_ack(page_id, layer_name, &peer_did, layer_permit, &decrypted_data, state_vector, state).await;
389→        } else {
390→            self.handle_layer_permit_ack(page_id, layer_name, &peer_did, layer_permit, &decrypted_data, state).await;
391→        }
392→    }
393→
394→    /// Handle LayerSubscribeAck containing a layer_authority permit (node received from creator)
395→    ///
396→    /// **Context**: We're the node, a creator responded with authority for a dynamic layer
397→    /// **We do**: Send StoreLayerAuthority to Scribe (stores authority, applies data, fans out)
398→    #[instrument(skip(self, state, data, state_vector), fields(page_id = %page_id, layer = %layer_name, creator = %creator_did))]
399→    async fn handle_authority_ack(
400→        &self,
401→        page_id: &str,
402→        layer_name: &str,
403→        creator_did: &str,
404→        authority_token: &str,
405→        data: &[u8],
406→        state_vector: &[u8],
407→        state: &mut PeerActorState<C>,
408→    ) {
409→        info!("Received layer_authority for layer={} from creator={}", layer_name, creator_did);
410→
411→        let scribe = match state.page_subscriptions.get(page_id) {
412→            Some(sub) => sub.scribe.clone(),
413→            None => {
414→                warn!("No page subscription for page={}, cannot store authority", page_id);
415→                return;
416→            }
417→        };
418→
419→        // Delegate to Scribe: store authority, apply data, fan out to authorized users
420→        if let Err(e) = scribe.cast(ScribeMessage::StoreLayerAuthority {
421→            layer_name: layer_name.to_string(),
422→            creator_did: creator_did.to_string(),
423→            authority_token: authority_token.to_string(),
424→            layer_data: data.to_vec(),
425→            state_vector: state_vector.to_vec(),
426→        }) {
427→            error!("Failed to send StoreLayerAuthority to Scribe: {}", e);
428→            return;
429→        }
430→
431→        // Authorize creator as subscriber for bidirectional sync
432→        scribe.cast(ScribeMessage::AuthorizeLayerSubscriber {
433→            layer_name: layer_name.to_string(),
434→            subscriber_did: creator_did.to_string(),
435→        }).ok();
436→
437→        // Mark creator's __sync_meta entry as synced
438→        let meta_layer = format!("__sync_meta:{}", creator_did);
439→        let _ = scribe.cast(ScribeMessage::UpdateFromJson {
440→            layer_name: meta_layer,
441→            path: layer_name.to_string(),
442→            value: serde_json::json!(true),
443→            reply: None,
444→        });
445→
446→        info!("Stored authority and initiated fanout for layer={}", layer_name);
447→    }
448→
449→    /// Handle LayerSubscribeAck containing a layer_permit (user received from node)
450→    ///
451→    /// **Context**: We're the user, node responded with access permit for a dynamic layer
452→    /// **We do**: Store permit, apply data to Scribe, authorize node, mark synced
453→    #[instrument(skip(self, state, data), fields(page_id = %page_id, layer = %layer_name, node = %node_did))]
454→    async fn handle_layer_permit_ack(
455→        &self,
456→        page_id: &str,
457→        layer_name: &str,
458→        node_did: &str,
459→        layer_permit: &str,
460→        data: &[u8],
461→        state: &mut PeerActorState<C>,
462→    ) {
463→        info!("Received layer_permit for layer={} from node={}", layer_name, node_did);
464→
465→        // Store layer permit
466→        let full_layer_name = format!("{}/{}", page_id, layer_name);
467→        let our_did = match state.butler.get_identity().await {
468→            Ok(identity) => identity.did().to_string(),
469→            Err(e) => {
470→                error!("Failed to get our identity: {}", e);
471→                return;
472→            }
473→        };
474→
475→        if let Err(e) = state.butler.permits().store_layer_permit(
476→            page_id, &our_did, &full_layer_name, layer_permit,
477→        ) {
478→            error!("Failed to store layer permit: {}", e);
479→            return;
480→        }
481→
482→        info!("Stored layer permit for layer={}", full_layer_name);
483→
484→        // Apply data to Scribe
485→        if let Some(subscription) = state.page_subscriptions.get(page_id) {
486→            let (reply_tx, reply_rx) = tokio::sync::oneshot::channel();
487→            if let Err(e) = subscription.scribe.cast(ScribeMessage::ApplyUpdateWithResult {
488→                layer_name: layer_name.to_string(),
489→                update: data.to_vec(),
490→                from_peer: Some((node_did.to_string(), self.node_id.to_string())),
491→                permit: Some(layer_permit.to_string()),
492→                reply: reply_tx,
493→            }) {
494→                error!("Failed to send ApplyUpdate for LayerSubscribeAck: {}", e);
495→                return;
496→            }
497→
498→            match reply_rx.await {
499→                Ok(Ok(())) => {
500→                    info!("Applied LayerSubscribeAck data for layer={}", layer_name);
501→                }
502→                Ok(Err(e)) => {
503→                    warn!("Scribe rejected LayerSubscribeAck data for layer={}: {}", layer_name, e);
504→                }
505→                Err(_) => {
506→                    error!("ApplyUpdate reply dropped for layer={}", layer_name);
507→                    return;
508→                }
509→            }
510→
511→            // Authorize node as subscriber for bidirectional sync
512→            subscription.scribe.cast(ScribeMessage::AuthorizeLayerSubscriber {
513→                layer_name: layer_name.to_string(),
514→                subscriber_did: node_did.to_string(),
515→            }).ok();
516→            info!("Authorized node {} on layer={}", node_did, layer_name);
517→
518→            // Mark __sync_meta entry as synced
519→            subscription.scribe.cast(ScribeMessage::MarkSyncMetaSynced {
520→                layer_name: layer_name.to_string(),
521→            }).ok();
522→        } else {
523→            warn!("No page subscription for page={}, cannot apply LayerSubscribeAck", page_id);
524→        }
525→    }
526→}
