 720→                //
 721→                // **Context**: Timing race — __sync_meta broadcasts immediately (node is
 722→                // subscriber), but creator's dynamic layer data may not have synced yet.
 723→                // Peer discovers the entry in __sync_meta and sends LayerSubscribe before
 724→                // the layer exists on node. We create an empty layer; creator's data will
 725→                // arrive later via normal SyncOffer and broadcast to the now-subscribed peer.
 726→                if !state.units.contains_key(&bare) {
 727→                    if let Some(ref permit) = state.our_permit {
 728→                        if crate::layer_unit::find_matching_dynamic_schema(permit, &bare, &state.page_id).is_some() {
 729→                            info!(layer = %bare, "Creating empty dynamic layer for early LayerSubscribe");
 730→                            let mut unit = crate::layer_unit::LayerUnit::new_empty();
 731→                            unit.set_local_only(false);
