 885→                    subs.and_then(|s| {
 886→                        s.get(&(from_did.clone(), device_id.clone()))
 887→                            .map(|info| info.permit.can_send_ephemeral(&func))
 888→                    }).unwrap_or(false) // Unknown sender = reject
 889→                };
 890→
 891→                if !can_send {
 892→                    warn!(
 893→                        page_id = %state.page_id,
 894→                        from_did = %from_did,
 895→                        func = %func,
 896→                        "Remote structured ephemeral rejected - func not allowed"
 897→                    );
 898→                    return Ok(());
 899→                }
 900→
 901→                // Emit to local app subscribers
 902→                emit_structured_ephemeral(state, &from_did, &func, &args);
 903→
 904→                debug!(
 905→                    page_id = %state.page_id,
 906→                    from_did = %from_did,
 907→                    func = %func,
 908→                    "Processed remote structured ephemeral"
 909→                );
 910→            }
 911→
 912→            // Note: Ephemeral events now go through SubscribeToPageUpdates (PageUpdate::Ephemeral)
 913→
 914→            // Derivation operations (now handled by kunki/LuaRuntime externally)
 915→            ScribeMessage::RebuildDerived { target: _, reply } => {
 916→                // Derivation is now handled by kunki, not Scribe
 917→                let _ = reply.send(Err("Derivation is handled externally by kunki".to_string()));
 918→            }
 919→
 920→            ScribeMessage::RebuildAllDerived { reply } => {
 921→                // Derivation is now handled by kunki, not Scribe
 922→                let _ = reply.send(Err("Derivation is handled externally by kunki".to_string()));
 923→            }
 924→
 925→            ScribeMessage::IsDerivationEnabled { reply } => {
 926→                // Derivation is now external, Scribe always returns false
 927→                let _ = reply.send(false);
 928→            }
 929→
 930→            ScribeMessage::CreateDerivedLayer { target_layer } => {
 931→                let target_layer = normalize_layer_name(&target_layer, &state.page_id);
 932→                // Create the derived layer (empty) so it exists for subscribers
 933→                if !state.units.contains_key(&target_layer) {
 934→                    let unit = LayerUnit::new_empty();
 935→                    let _ = unit.layer().loro().get_map(target_layer.clone());
 936→                    unit.layer().commit();
 937→                    state.units.insert(target_layer.clone(), unit);
 938→                    info!(target = %target_layer, "Created empty derived layer");
 939→
 940→                    // Set up observer for the new layer
 941→                    loro_observer::setup_layer_observer(state, &target_layer);
 942→                }
 943→            }
 944→
 945→            ScribeMessage::GetAppFiles { app_name, reply } => {
 946→                // Use bare layer name (Scribe uses bare names, no page_id/ prefix)
 947→                let layer_name = format!("app:{}", app_name);
 948→                let result = if let Some(unit) = state.units.get(&layer_name) {
 949→                    Ok(unit.layer().get_all_files())
 950→                } else {
 951→                    Err(format!("App layer '{}' not found", layer_name))
 952→                };
 953→                let _ = reply.send(result);
 954→            }
 955→
 956→            ScribeMessage::GetSubscriberCount { reply } => {
 957→                let count = state.subscribers.read()
 958→                    .map(|s| s.len())
 959→                    .unwrap_or(0);
 960→                let _ = reply.send(count);
 961→            }
 962→
 963→            ScribeMessage::RefreshApp { app_name: _, app_dir: _, reply } => {
 964→                // RefreshApp requires filesystem access which is handled by butler's refresh service
 965→                // This stub returns an error - callers should use butler's refresh functionality instead
 966→                let _ = reply.send(Err("RefreshApp not supported in base Scribe - use butler's refresh service".to_string()));
 967→            }
 968→        }
 969→
 970→        Ok(())
 971→    }
 972→
 973→    #[instrument(skip_all, fields(page_id = %state.page_id))]
 974→    async fn post_stop(
 975→        &self,
 976→        _myself: ActorRef<Self::Msg>,
 977→        state: &mut Self::State,
 978→    ) -> std::result::Result<(), ActorProcessingErr> {
 979→        // Flush any dirty layers before stopping
 980→        let has_dirty = state.units.values().any(|u| u.is_dirty());
 981→        if has_dirty {
 982→            let dirty_count = state.units.values().filter(|u| u.is_dirty()).count();
 983→            info!(page_id = %state.page_id, dirty_count = dirty_count, "Flushing dirty layers on shutdown");
 984→            sync::handle_flush(state).await;
 985→        }
 986→
 987→        // Stop node script if running
 988→        if let Some(tx) = state.node_script_shutdown.take() {
 989→            info!(page_id = %state.page_id, "Stopping node script tick loop");
 990→            let _ = tx.send(()).await;
 991→        }
 992→
 993→        info!(page_id = %state.page_id, "Scribe stopped");
 994→        Ok(())
 995→    }
 996→}
 997→
 998→// Helper Methods
 999→
1000→impl Scribe {
1001→    /// Handle JSON update from UI (CEL commit())
1002→    ///
1003→    /// **Broadcast**: Handled automatically by Loro observer after commit()
1004→    #[instrument(skip_all, fields(page_id = %state.page_id, layer = %layer_name, path = %path))]
1005→    async fn handle_update_from_json(
1006→        &self,
1007→        state: &mut ScribeState,
1008→        layer_name: &str,
1009→        path: &str,
1010→        value: serde_json::Value,
1011→    ) -> Result<()> {
1012→        info!(layer = %layer_name, path = %path, "Updating layer from JSON");
1013→
1014→        // Get or create the layer unit
1015→        let unit = state
1016→            .units
1017→            .entry(layer_name.to_string())
1018→            .or_insert_with(LayerUnit::new_empty);
1019→
1020→        // Convert JSON to Loro and update
1021→        unit.layer()
1022→            .set_from_json(path, &value)
1023→            .map_err(|e| ScribeError::CrdtError(format!("Layer: {}", e)))?;
1024→
1025→        // Commit to trigger Loro observer (which broadcasts to peers + notifies UI)
1026→        unit.layer().commit();
1027→
1028→        // Mark as dirty for persistence
1029→        unit.mark_dirty();
1030→
1031→        debug!("Layer update from JSON complete, observer will broadcast");
1032→        Ok(())
1033→    }
1034→}
1035→
1036→/// Issue a layer permit for a LayerSubscribe request
1037→///
1038→/// **Context**: Peer sent LayerSubscribe, we need to issue a permit.
1039→/// Permit-driven priority:
1040→/// 1. Self-permit check: I'm the creator → issue authority permit
1041→/// 2. Stored authority check: I'm the node → issue layer_permit
1042→/// 3. Static layer: defined in our permit → issue layer_permit
1043→fn issue_layer_permit_for_subscribe(
1044→    state: &ScribeState,
1045→    peer_did: &str,
1046→    bare_layer_name: &str,
1047→    full_layer_name: &str,
1048→) -> std::result::Result<String, String> {
1049→    let issuer = state.permit_issuer.as_ref()
1050→        .ok_or_else(|| "No permit issuer (not node mode)".to_string())?;
1051→
1052→    // 1. Self-permit check: I'm the creator
1053→    // If we have a self-permit for this layer, issue authority permit to requester (node)
1054→    match issuer.get_layer_authority_permit(&state.our_did, full_layer_name) {
1055→        Ok(Some((_version, self_authority_token))) => {
1056→            // Parse self-permit to get authorized_peers and config
1057→            if let Ok(self_permit) = gurkha::Permit::from_token(&self_authority_token) {
1058→                let authorized_peers = self_permit.get_fact("authorized_peers")
1059→                    .and_then(|v| {
1060→                        v.as_array().map(|arr| {
1061→                            arr.iter()
1062→                                .filter_map(|v| v.as_str().map(String::from))
1063→                                .collect::<Vec<_>>()
1064→                        })
1065→                    });
1066→                let config = self_permit.layers().get(full_layer_name)
1067→                    .or_else(|| self_permit.layers().get(bare_layer_name))
1068→                    .cloned()
1069→                    .unwrap_or(gurkha::LayerConfig { sync: true, write: true, layer_type: None });
1070→
1071→                match issuer.issue_layer_authority_permit(
1072→                    peer_did, full_layer_name, config, authorized_peers, _version + 1,
1073→                ) {
1074→                    Ok((token, _cid)) => {
1075→                        info!(layer = %full_layer_name, peer = %peer_did, "Issued authority permit (creator → node)");
1076→                        return Ok(token);
1077→                    }
1078→                    Err(e) => {
1079→                        warn!(error = %e, "Failed to issue authority permit from self-permit");
1080→                    }
1081→                }
1082→            }
1083→        }
1084→        Ok(None) => {}
1085→        Err(e) => {
1086→            warn!(error = %e, "Error looking up self-permit");
1087→        }
1088→    }
1089→
1090→    // 2. Stored authority check: I'm the node with authority from a creator
1091→    match issuer.get_authority_for_layer(full_layer_name) {
1092→        Ok(Some((_creator_did, _version, authority_token))) => {
1093→            // Parse authority to check authorized_peers
1094→            if let Ok(authority_permit) = gurkha::Permit::from_token(&authority_token) {
1095→                let authorized_peers = authority_permit.get_fact("authorized_peers");
1096→                let is_authorized = match authorized_peers {
1097→                    None => true, // No authorized_peers fact → open grant
1098→                    Some(serde_json::Value::Null) => true, // Explicit null → open grant
1099→                    Some(serde_json::Value::Array(arr)) => {
1100→                        arr.iter().any(|v| v.as_str() == Some(peer_did))
1101→                    }
1102→                    _ => false,
1103→                };
1104→
1105→                if is_authorized {
1106→                    let config = authority_permit.layers().get(full_layer_name)
1107→                        .or_else(|| authority_permit.layers().get(bare_layer_name))
1108→                        .cloned()
1109→                        .unwrap_or(gurkha::LayerConfig { sync: true, write: true, layer_type: None });
1110→
1111→                    let intent_cid = gurkha::crypto::get_permit_cid(&authority_token).ok();
1112→                    match issuer.issue_layer_permit(
1113→                        peer_did, full_layer_name, config, intent_cid.as_deref(),
1114→                    ) {
1115→                        Ok((token, _cid)) => {
1116→                            info!(layer = %full_layer_name, peer = %peer_did, "Issued layer permit from stored authority");
1117→                            return Ok(token);
1118→                        }
1119→                        Err(e) => {
1120→                            warn!(error = %e, "Failed to issue permit from stored authority");
1121→                        }
1122→                    }
1123→                } else {
1124→                    warn!(layer = %full_layer_name, peer = %peer_did, "Peer not in authorized_peers list");
1125→                }
1126→            }
1127→        }
1128→        Ok(None) => {}
1129→        Err(e) => {
1130→            warn!(error = %e, "Error looking up authority for layer");
1131→        }
1132→    }
1133→
1134→    // 3. Static layer from our own permit
1135→    if let Some(ref our_permit) = state.our_permit {
1136→        if let Some(config) = our_permit.layers().get(full_layer_name) {
1137→            match issuer.issue_layer_permit(peer_did, full_layer_name, config.clone(), None) {
1138→                Ok((token, _cid)) => return Ok(token),
1139→                Err(e) => {
1140→                    warn!(error = %e, layer = %full_layer_name, "Failed to issue permit for static layer");
1141→                }
1142→            }
1143→        }
1144→    }
1145→
1146→    Err(format!("Cannot issue layer permit for {} to {}", full_layer_name, peer_did))
1147→}
1148→
1149→/// Handle StoreLayerAuthority message (node-side)
1150→///
1151→/// **Context**: Node received authority from creator via LayerSubscribeAck.
1152→/// **We do**: Store authority, apply layer data, fan out to authorized peers.
1153→fn handle_store_layer_authority(
1154→    state: &mut ScribeState,
1155→    layer_name: &str,
1156→    creator_did: &str,
1157→    authority_token: &str,
1158→    layer_data: &[u8],
1159→) {
1160→    let bare = crate::state::normalize_layer_name(layer_name, &state.page_id);
1161→
1162→    // 1. Store authority permit via PermitIssuer
1163→    if let Some(ref issuer) = state.permit_issuer {
1164→        if let Err(e) = issuer.store_authority_permit(creator_did, layer_name, authority_token, 1) {
1165→            error!(layer = %layer_name, error = %e, "Failed to store authority permit");
1166→            return;
1167→        }
1168→        info!(layer = %layer_name, creator = %creator_did, "Stored authority permit from creator");
1169→    }
1170→
1171→    // 2. Create LayerUnit if needed and apply layer data
1172→    if !state.units.contains_key(&bare) {
1173→        let mut unit = LayerUnit::new_empty();
1174→        unit.set_local_only(false);
1175→        unit.is_dynamic = true;
1176→        state.units.insert(bare.clone(), unit);
1177→        loro_observer::setup_layer_observer(state, &bare);
1178→        info!(layer = %bare, "Created dynamic layer from authority");
1179→    }
1180→
1181→    if !layer_data.is_empty() {
1182→        if let Some(unit) = state.units.get(&bare) {
1183→            if let Err(e) = unit.layer().apply(layer_data) {
1184→                warn!(layer = %bare, error = %e, "Failed to apply layer data from authority");
1185→            } else {
1186→                unit.layer().commit();
1187→                if let Some(unit) = state.units.get_mut(&bare) {
1188→                    unit.mark_dirty();
1189→                }
1190→            }
1191→        }
1192→    }
1193→
1194→    // 3. Parse authorized_peers from authority and fan out
1195→    if let Ok(authority_permit) = gurkha::Permit::from_token(authority_token) {
1196→        let authorized_peers = authority_permit.get_fact("authorized_peers")
1197→            .and_then(|v| match v {
1198→                serde_json::Value::Null => None,
1199→                serde_json::Value::Array(arr) => Some(
1200→                    arr.iter()
1201→                        .filter_map(|v| v.as_str().map(String::from))
1202→                        .collect::<Vec<_>>()
1203→                ),
1204→                _ => None,
1205→            });
1206→
1207→        handle_fan_out_layer_to_users(state, &bare, authorized_peers.as_deref());
1208→    }
1209→
1210→    // 4. Mark creator's __sync_meta entry as synced
1211→    sync::sync_meta::mark_entry_synced(state, creator_did, &bare);
1212→}
1213→
1214→/// Fan out a layer entry to authorized users' __sync_meta
1215→///
1216→/// **Context**: Node needs to notify authorized peers about a new dynamic layer.
1217→/// **authorized_peers**: None = all subscribers, Some(list) = specific DIDs only.
1218→fn handle_fan_out_layer_to_users(
1219→    state: &mut ScribeState,
1220→    layer_name: &str,
1221→    authorized_peers: Option<&[String]>,
1222→) {
1223→    // Collect all subscriber DIDs
1224→    let all_peer_dids: Vec<String> = {
1225→        let mut dids = Vec::new();
1226→        if let Ok(subs) = state.subscribers.read() {
1227→            for ((did, _), _) in subs.iter() {
1228→                if !dids.contains(did) {
1229→                    dids.push(did.clone());
1230→                }
1231→            }
1232→        }
1233→        dids
1234→    };
1235→
1236→    let target_dids: Vec<&String> = match authorized_peers {
1237→        None => all_peer_dids.iter().collect(),
1238→        Some(list) => all_peer_dids.iter()
1239→            .filter(|did| list.iter().any(|d| d == *did))
1240→            .collect(),
1241→    };
1242→
1243→    for peer_did in target_dids {
1244→        let peer_entries = sync::sync_meta::read_sync_meta_entries(state, peer_did);
1245→        let already_has = peer_entries.iter().any(|e| e.layer_name == layer_name);
1246→        if !already_has {
1247→            sync::sync_meta::write_sync_meta_entry(state, peer_did, layer_name, false);
1248→            info!(
1249→                layer = %layer_name,
1250→                peer_did = %peer_did,
1251→                "Fan out: wrote dynamic entry to peer's __sync_meta"
1252→            );
1253→        }
1254→    }
1255→}
1256→
1257→// Tests
1258→
1259→#[cfg(test)]
1260→mod tests {
1261→    use super::*;
1262→    use crate::test_fixtures::node_scribe_args;
1263→    use std::time::Duration;
1264→
1265→    /// Test that Scribe with no subscribers doesn't crash on ephemeral send
1266→    #[tokio::test]
1267→    async fn test_ephemeral_with_no_subscribers() {
1268→        let args = node_scribe_args("test-page-456");
1269→        let (scribe_ref, _handle) = ractor::Actor::spawn(
1270→            Some("test-scribe-no-subs".to_string()),
1271→            Scribe,
1272→            args,
1273→        ).await.expect("Failed to spawn Scribe");
1274→
1275→        // Send ephemeral with no subscribers - should not crash
1276→        scribe_ref.cast(ScribeMessage::SendStructuredEphemeral {
1277→            func: "typing".to_string(),
1278→            args: serde_json::json!({"user": "TestUser"}),
1279→        }).expect("Failed to send ephemeral");
1280→
1281→        // Small delay to ensure message is processed
1282→        tokio::time::sleep(Duration::from_millis(50)).await;
1283→
1284→        println!("✓ Ephemeral with no subscribers handled gracefully");
1285→        scribe_ref.stop(Some("test complete".to_string()));
1286→    }
