 845→                let ephemeral_funcs = state.our_permit
 846→                    .as_ref()
 847→                    .map(|p| p.ephemeral_funcs().to_vec())
 848→                    .unwrap_or_default();
 849→                debug!(
 850→                    page_id = %state.page_id,
