 857→
 858→                // Validate func against our permit's ephemeral_funcs (if set)
 859→                // Empty ephemeral_funcs list means all funcs allowed
 860→                let can_send = state.our_permit
 861→                    .as_ref()
 862→                    .map(|p| p.can_send_ephemeral(&func))
 863→                    .unwrap_or(true); // No permit = allow (local mode)
 864→
 865→                if !can_send {
