 875→                // PeerActor should be subscribed to this Scribe with ephemeral_tx
 876→                // Include from_did so relayed messages preserve original sender identity
 877→                let payload = serde_json::json!({
 878→                    "type": "structured",
 879→                    "from_did": our_did,
 880→                    "func": func,
 881→                    "args": args
 882→                });
 883→                if let Ok(bytes) = serde_json::to_vec(&payload) {
 884→                    debug!(
 885→                        page_id = %state.page_id,
 886→                        func = %func,
 887→                        "Broadcasting structured ephemeral to PeerActor subscribers"
 888→                    );
 889→                    broadcast_ephemeral_to_subscribers(state, &bytes, None);
 890→                }
 891→            }
 892→
 893→            ScribeMessage::RemoteStructuredEphemeral { from_did, device_id, func, args } => {
 894→                // Validate func against sender's permit
 895→                let can_send = {
 896→                    let subs = state.subscribers.read().ok();
 897→                    subs.and_then(|s| {
 898→                        s.get(&(from_did.clone(), device_id.clone()))
 899→                            .map(|info| info.permit.can_send_ephemeral(&func))
 900→                    }).unwrap_or(false) // Unknown sender = reject
 901→                };
 902→
 903→                if !can_send {
 904→                    warn!(
 905→                        page_id = %state.page_id,
 906→                        from_did = %from_did,
 907→                        func = %func,
 908→                        "Remote structured ephemeral rejected - func not allowed"
 909→                    );
 910→                    return Ok(());
 911→                }
 912→
 913→                // Emit to local app subscribers
 914→                emit_structured_ephemeral(state, &from_did, &func, &args);
 915→
 916→                debug!(
 917→                    page_id = %state.page_id,
 918→                    from_did = %from_did,
 919→                    func = %func,
 920→                    "Processed remote structured ephemeral"
 921→                );
 922→            }
 923→
 924→            // Note: Ephemeral events now go through SubscribeToPageUpdates (PageUpdate::Ephemeral)
 925→
 926→            // Derivation operations (now handled by kunki/LuaRuntime externally)
 927→            ScribeMessage::RebuildDerived { target: _, reply } => {
 928→                // Derivation is now handled by kunki, not Scribe
 929→                let _ = reply.send(Err("Derivation is handled externally by kunki".to_string()));
 930→            }
 931→
 932→            ScribeMessage::RebuildAllDerived { reply } => {
 933→                // Derivation is now handled by kunki, not Scribe
 934→                let _ = reply.send(Err("Derivation is handled externally by kunki".to_string()));
 935→            }
 936→
 937→            ScribeMessage::IsDerivationEnabled { reply } => {
 938→                // Derivation is now external, Scribe always returns false
 939→                let _ = reply.send(false);
 940→            }
 941→
 942→            ScribeMessage::CreateDerivedLayer { target_layer } => {
 943→                let target_layer = normalize_layer_name(&target_layer, &state.page_id);
 944→                // Create the derived layer (empty) so it exists for subscribers
 945→                if !state.units.contains_key(&target_layer) {
 946→                    let unit = LayerUnit::new_empty();
 947→                    let _ = unit.layer().loro().get_map(target_layer.clone());
 948→                    unit.layer().commit();
 949→                    state.units.insert(target_layer.clone(), unit);
 950→                    info!(target = %target_layer, "Created empty derived layer");
 951→
 952→                    // Set up observer for the new layer
 953→                    loro_observer::setup_layer_observer(state, &target_layer);
 954→                }
 955→            }
 956→
 957→            ScribeMessage::GetAppFiles { app_name, reply } => {
 958→                // Use bare layer name (Scribe uses bare names, no page_id/ prefix)
 959→                let layer_name = format!("app:{}", app_name);
 960→                let result = if let Some(unit) = state.units.get(&layer_name) {
 961→                    Ok(unit.layer().get_all_files())
 962→                } else {
 963→                    Err(format!("App layer '{}' not found", layer_name))
 964→                };
 965→                let _ = reply.send(result);
 966→            }
 967→
 968→            ScribeMessage::GetSubscriberCount { reply } => {
 969→                let count = state.subscribers.read()
 970→                    .map(|s| s.len())
 971→                    .unwrap_or(0);
 972→                let _ = reply.send(count);
 973→            }
 974→
 975→            ScribeMessage::RefreshApp { app_name: _, app_dir: _, reply } => {
 976→                // RefreshApp requires filesystem access which is handled by butler's refresh service
 977→                // This stub returns an error - callers should use butler's refresh functionality instead
 978→                let _ = reply.send(Err("RefreshApp not supported in base Scribe - use butler's refresh service".to_string()));
 979→            }
 980→        }
 981→
 982→        Ok(())
 983→    }
 984→
 985→    #[instrument(skip_all, fields(page_id = %state.page_id))]
 986→    async fn post_stop(
 987→        &self,
 988→        _myself: ActorRef<Self::Msg>,
 989→        state: &mut Self::State,
 990→    ) -> std::result::Result<(), ActorProcessingErr> {
 991→        // Flush any dirty layers before stopping
 992→        let has_dirty = state.units.values().any(|u| u.is_dirty());
 993→        if has_dirty {
 994→            let dirty_count = state.units.values().filter(|u| u.is_dirty()).count();
 995→            info!(page_id = %state.page_id, dirty_count = dirty_count, "Flushing dirty layers on shutdown");
 996→            sync::handle_flush(state).await;
 997→        }
 998→
 999→        // Stop node script if running
1000→        if let Some(tx) = state.node_script_shutdown.take() {
1001→            info!(page_id = %state.page_id, "Stopping node script tick loop");
1002→            let _ = tx.send(()).await;
1003→        }
1004→
1005→        info!(page_id = %state.page_id, "Scribe stopped");
1006→        Ok(())
1007→    }
1008→}
