1011→
1012→impl Scribe {
1013→    /// Handle JSON update from UI (CEL commit())
1014→    ///
1015→    /// **Broadcast**: Handled automatically by Loro observer after commit()
1016→    #[instrument(skip_all, fields(page_id = %state.page_id, layer = %layer_name, path = %path))]
1017→    async fn handle_update_from_json(
1018→        &self,
1019→        state: &mut ScribeState,
1020→        layer_name: &str,
1021→        path: &str,
1022→        value: serde_json::Value,
1023→    ) -> Result<()> {
1024→        info!(layer = %layer_name, path = %path, "Updating layer from JSON");
1025→
1026→        // Get or create the layer unit
1027→        let unit = state
1028→            .units
1029→            .entry(layer_name.to_string())
1030→            .or_insert_with(LayerUnit::new_empty);
1031→
1032→        // Convert JSON to Loro and update
1033→        unit.layer()
1034→            .set_from_json(path, &value)
1035→            .map_err(|e| ScribeError::CrdtError(format!("Layer: {}", e)))?;
1036→
1037→        // Commit to trigger Loro observer (which broadcasts to peers + notifies UI)
1038→        unit.layer().commit();
1039→
1040→        // Mark as dirty for persistence
1041→        unit.mark_dirty();
1042→
1043→        debug!("Layer update from JSON complete, observer will broadcast");
1044→        Ok(())
1045→    }
1046→}
