1048→/// Issue a layer permit for a LayerSubscribe request
1049→///
1050→/// **Context**: Peer sent LayerSubscribe, we need to issue a permit.
1051→/// Permit-driven priority:
1052→/// 1. Self-permit check: I'm the creator → issue authority permit
1053→/// 2. Stored authority check: I'm the node → issue layer_permit
1054→/// 3. Static layer: defined in our permit → issue layer_permit
1055→fn issue_layer_permit_for_subscribe(
1056→    state: &ScribeState,
1057→    peer_did: &str,
1058→    bare_layer_name: &str,
1059→    full_layer_name: &str,
1060→) -> std::result::Result<String, String> {
1061→    let issuer = state.permit_issuer.as_ref()
1062→        .ok_or_else(|| {
1063→            state.emit_permit_issue_capture(full_layer_name, peer_did, "none", "err", Some("no permit issuer"));
1064→            "No permit issuer (not node mode)".to_string()
1065→        })?;
1066→
1067→    // 1. Self-permit check: I'm the creator
1068→    // If we have a self-permit for this layer, issue authority permit to requester (node)
1069→    match issuer.get_layer_authority_permit(&state.our_did, full_layer_name) {
1070→        Ok(Some((_version, self_authority_token))) => {
1071→            // Parse self-permit to get authorized_peers and config
1072→            if let Ok(self_permit) = gurkha::Permit::from_token(&self_authority_token) {
1073→                let authorized_peers = self_permit.get_fact("authorized_peers")
1074→                    .and_then(|v| {
1075→                        v.as_array().map(|arr| {
1076→                            arr.iter()
1077→                                .filter_map(|v| v.as_str().map(String::from))
1078→                                .collect::<Vec<_>>()
1079→                        })
1080→                    });
1081→                let config = self_permit.layers().get(full_layer_name)
1082→                    .or_else(|| self_permit.layers().get(bare_layer_name))
1083→                    .cloned()
1084→                    .unwrap_or(gurkha::LayerConfig { sync: true, write: true, layer_type: None });
1085→
1086→                match issuer.issue_layer_authority_permit(
1087→                    peer_did, full_layer_name, config, authorized_peers, _version + 1,
1088→                ) {
1089→                    Ok((token, _cid)) => {
1090→                        info!(layer = %full_layer_name, peer = %peer_did, "Issued authority permit (creator → node)");
1091→                        state.emit_permit_issue_capture(full_layer_name, peer_did, "self_permit", "ok", None);
1092→                        return Ok(token);
1093→                    }
1094→                    Err(e) => {
1095→                        warn!(error = %e, "Failed to issue authority permit from self-permit");
1096→                        state.emit_permit_issue_capture(full_layer_name, peer_did, "self_permit", "err", Some(&e.to_string()));
1097→                    }
1098→                }
1099→            }
1100→        }
1101→        Ok(None) => {
1102→            state.emit_permit_issue_capture(full_layer_name, peer_did, "self_permit", "skip", Some("no self-permit found"));
1103→        }
1104→        Err(e) => {
1105→            warn!(error = %e, "Error looking up self-permit");
1106→            state.emit_permit_issue_capture(full_layer_name, peer_did, "self_permit", "err", Some(&e.to_string()));
1107→        }
1108→    }
1109→
1110→    // 2. Stored authority check: I'm the node with authority from a creator
1111→    match issuer.get_authority_for_layer(full_layer_name) {
1112→        Ok(Some((_creator_did, _version, authority_token))) => {
1113→            // Parse authority to check authorized_peers
1114→            if let Ok(authority_permit) = gurkha::Permit::from_token(&authority_token) {
1115→                let authorized_peers = authority_permit.get_fact("authorized_peers");
1116→                let is_authorized = match authorized_peers {
1117→                    None => true, // No authorized_peers fact → open grant
1118→                    Some(serde_json::Value::Null) => true, // Explicit null → open grant
1119→                    Some(serde_json::Value::Array(arr)) => {
1120→                        arr.iter().any(|v| v.as_str() == Some(peer_did))
1121→                    }
1122→                    _ => false,
1123→                };
1124→
1125→                if is_authorized {
1126→                    let config = authority_permit.layers().get(full_layer_name)
1127→                        .or_else(|| authority_permit.layers().get(bare_layer_name))
1128→                        .cloned()
1129→                        .unwrap_or(gurkha::LayerConfig { sync: true, write: true, layer_type: None });
1130→
1131→                    let intent_cid = gurkha::crypto::get_permit_cid(&authority_token).ok();
1132→                    match issuer.issue_layer_permit(
1133→                        peer_did, full_layer_name, config, intent_cid.as_deref(),
1134→                    ) {
1135→                        Ok((token, _cid)) => {
1136→                            info!(layer = %full_layer_name, peer = %peer_did, "Issued layer permit from stored authority");
1137→                            state.emit_permit_issue_capture(full_layer_name, peer_did, "stored_authority", "ok", None);
1138→                            return Ok(token);
1139→                        }
1140→                        Err(e) => {
1141→                            warn!(error = %e, "Failed to issue permit from stored authority");
1142→                            state.emit_permit_issue_capture(full_layer_name, peer_did, "stored_authority", "err", Some(&e.to_string()));
1143→                        }
1144→                    }
1145→                } else {
1146→                    warn!(layer = %full_layer_name, peer = %peer_did, "Peer not in authorized_peers list");
1147→                    state.emit_permit_issue_capture(full_layer_name, peer_did, "stored_authority", "err", Some("peer not in authorized_peers"));
1148→                }
1149→            }
1150→        }
1151→        Ok(None) => {
1152→            state.emit_permit_issue_capture(full_layer_name, peer_did, "stored_authority", "skip", Some("no authority found"));
1153→        }
1154→        Err(e) => {
1155→            warn!(error = %e, "Error looking up authority for layer");
1156→            state.emit_permit_issue_capture(full_layer_name, peer_did, "stored_authority", "err", Some(&e.to_string()));
1157→        }
1158→    }
1159→
1160→    // 3. Static layer from our own permit
1161→    if let Some(ref our_permit) = state.our_permit {
1162→        if let Some(config) = our_permit.layers().get(full_layer_name) {
1163→            match issuer.issue_layer_permit(peer_did, full_layer_name, config.clone(), None) {
1164→                Ok((token, _cid)) => {
1165→                    state.emit_permit_issue_capture(full_layer_name, peer_did, "static_layer", "ok", None);
1166→                    return Ok(token);
1167→                }
1168→                Err(e) => {
1169→                    warn!(error = %e, layer = %full_layer_name, "Failed to issue permit for static layer");
1170→                    state.emit_permit_issue_capture(full_layer_name, peer_did, "static_layer", "err", Some(&e.to_string()));
1171→                }
1172→            }
1173→        } else {
1174→            state.emit_permit_issue_capture(full_layer_name, peer_did, "static_layer", "skip", Some("layer not in our permit"));
1175→        }
1176→    }
1177→
1178→    state.emit_permit_issue_capture(full_layer_name, peer_did, "none", "err", Some("all paths exhausted"));
1179→    Err(format!("Cannot issue layer permit for {} to {}", full_layer_name, peer_did))
1180→}
1181→
1182→/// Handle StoreLayerAuthority message (node-side)
1183→///
1184→/// **Context**: Node received authority from creator via LayerSubscribeAck.
1185→/// **We do**: Store authority, apply layer data, fan out to authorized peers.
1186→fn handle_store_layer_authority(
1187→    state: &mut ScribeState,
1188→    layer_name: &str,
1189→    creator_did: &str,
1190→    authority_token: &str,
1191→    layer_data: &[u8],
1192→) {
1193→    let bare = crate::state::normalize_layer_name(layer_name, &state.page_id);
1194→
1195→    // 1. Store authority permit via PermitIssuer
1196→    if let Some(ref issuer) = state.permit_issuer {
1197→        if let Err(e) = issuer.store_authority_permit(creator_did, layer_name, authority_token, 1) {
1198→            error!(layer = %layer_name, error = %e, "Failed to store authority permit");
1199→            return;
1200→        }
1201→        info!(layer = %layer_name, creator = %creator_did, "Stored authority permit from creator");
1202→    }
1203→
1204→    // 2. Create LayerUnit if needed and apply layer data
1205→    if !state.units.contains_key(&bare) {
1206→        let mut unit = LayerUnit::new_empty();
1207→        unit.set_local_only(false);
1208→        unit.is_dynamic = true;
1209→        state.units.insert(bare.clone(), unit);
1210→        loro_observer::setup_layer_observer(state, &bare);
1211→        info!(layer = %bare, "Created dynamic layer from authority");
1212→    }
1213→
1214→    if !layer_data.is_empty() {
1215→        if let Some(unit) = state.units.get(&bare) {
1216→            if let Err(e) = unit.layer().apply(layer_data) {
1217→                warn!(layer = %bare, error = %e, "Failed to apply layer data from authority");
1218→            } else {
1219→                unit.layer().commit();
1220→                if let Some(unit) = state.units.get_mut(&bare) {
1221→                    unit.mark_dirty();
1222→                }
1223→            }
1224→        }
1225→    }
1226→
1227→    // 3. Parse authorized_peers from authority and fan out
1228→    if let Ok(authority_permit) = gurkha::Permit::from_token(authority_token) {
1229→        let authorized_peers = authority_permit.get_fact("authorized_peers")
1230→            .and_then(|v| match v {
1231→                serde_json::Value::Null => None,
1232→                serde_json::Value::Array(arr) => Some(
1233→                    arr.iter()
1234→                        .filter_map(|v| v.as_str().map(String::from))
1235→                        .collect::<Vec<_>>()
1236→                ),
1237→                _ => None,
1238→            });
1239→
1240→        handle_fan_out_layer_to_users(state, &bare, authorized_peers.as_deref());
1241→    }
1242→
1243→    // 4. Mark creator's __sync_meta entry as synced
1244→    sync::sync_meta::mark_entry_synced(state, creator_did, &bare);
1245→}
1246→
1247→/// Fan out a layer entry to authorized users' __sync_meta
1248→///
1249→/// **Context**: Node needs to notify authorized peers about a new dynamic layer.
1250→/// **authorized_peers**: None = all subscribers, Some(list) = specific DIDs only.
1251→fn handle_fan_out_layer_to_users(
1252→    state: &mut ScribeState,
1253→    layer_name: &str,
1254→    authorized_peers: Option<&[String]>,
1255→) {
1256→    // Collect all subscriber DIDs
1257→    let all_peer_dids: Vec<String> = {
1258→        let mut dids = Vec::new();
1259→        if let Ok(subs) = state.subscribers.read() {
1260→            for ((did, _), _) in subs.iter() {
1261→                if !dids.contains(did) {
1262→                    dids.push(did.clone());
1263→                }
1264→            }
1265→        }
1266→        dids
1267→    };
1268→
1269→    let target_dids: Vec<&String> = match authorized_peers {
1270→        None => all_peer_dids.iter().collect(),
1271→        Some(list) => all_peer_dids.iter()
1272→            .filter(|did| list.iter().any(|d| d == *did))
1273→            .collect(),
1274→    };
1275→
1276→    for peer_did in target_dids {
1277→        let peer_entries = sync::sync_meta::read_sync_meta_entries(state, peer_did);
1278→        let already_has = peer_entries.iter().any(|e| e.layer_name == layer_name);
1279→        if !already_has {
1280→            sync::sync_meta::write_sync_meta_entry(state, peer_did, layer_name, false);
1281→            info!(
1282→                layer = %layer_name,
1283→                peer_did = %peer_did,
1284→                "Fan out: wrote dynamic entry to peer's __sync_meta"
1285→            );
1286→        }
1287→    }
1288→}
