  1→//! Layer Subscribe Protocol (pull-based via __sync_meta)
  2→//!
  3→//! Handles the pull-based layer discovery and subscription flow:
  4→//! 1. Peer detects new entries in their __sync_meta (via SyncOffer)
  5→//! 2. Peer sends LayerSubscribe for each unsynced layer (with consent permit)
  6→//! 3. Responder validates, exports snapshot, issues permit, responds with LayerSubscribeAck
  7→//! 4. Subscriber decrypts data, stores permit, applies to Scribe, marks synced
  8→
  9→use tracing::{debug, error, info, warn, instrument};
 10→
 11→use crate::message::*;
 12→use transport::Connection;
 13→
 14→use super::guards::require_auth;
 15→use super::{PeerActor, PeerActorState};
 16→use butler::ScribeMessage;
 17→
 18→/// Default layer consent template — subscriber consents to receive layer sync updates
 19→const DEFAULT_LAYER_CONSENT_TEMPLATE: &str = r#"{
 20→  "consent_template": {
 21→    "token_type": "sync_layer_consent",
 22→    "operations": { "receive_updates": "allow" },
 23→    "auth_capabilities": { "accept_sync": true },
 24→    "relationship": "sync_consent"
 25→  }
 26→}"#;
 27→
 28→impl<C: Connection> PeerActor<C> {
 29→
 30→    /// Emit a layer_subscribe_protocol capture event
 31→    ///
 32→    /// **Context**: Traces LayerSubscribe/LayerSubscribeAck outcomes for observability
 33→    fn emit_layer_subscribe_protocol_capture(
 34→        capture_tx: &Option<tokio::sync::broadcast::Sender<String>>,
 35→        direction: &str,
 36→        page_id: &str,
 37→        layer: &str,
 38→        peer_did: &str,
 39→        result: &str,
 40→        error: Option<&str>,
 41→    ) {
 42→        if let Some(ref tx) = capture_tx {
 43→            let ts = std::time::SystemTime::now()
 44→                .duration_since(std::time::UNIX_EPOCH)
 45→                .map(|d| d.as_millis())
 46→                .unwrap_or(0);
 47→            if let Ok(json) = serde_json::to_string(&serde_json::json!({
 48→                "type": "layer_subscribe_protocol",
 49→                "ts": ts,
 50→                "direction": direction,
 51→                "page_id": page_id,
 52→                "layer": layer,
 53→                "peer_did": peer_did,
 54→                "result": result,
 55→                "error": error,
 56→            })) {
 57→                let _ = tx.send(json);
 58→            }
 59→        }
 60→    }
 61→
 62→    /// Issue a layer consent permit for a specific layer
 63→    ///
 64→    /// **Context**: Subscriber is about to send LayerSubscribe, needs consent permit
 65→    /// **Returns**: consent_permit token, or empty string on failure
 66→    async fn issue_layer_consent(
 67→        &self,
 68→        page_id: &str,
 69→        layer_name: &str,
 70→        state: &PeerActorState<C>,
 71→    ) -> String {
 72→        let (peer_did, _) = match require_auth(&state.state) {
 73→            Ok(info) => (info.0.to_string(), info.1.to_string()),
 74→            Err(_) => return String::new(),
 75→        };
 76→
 77→        let signing_key = match state.butler.signing_key().await {
 78→            Ok(key) => key,
 79→            Err(e) => {
 80→                warn!("Failed to get signing key for layer consent: {}", e);
 81→                return String::new();
 82→            }
 83→        };
 84→
 85→        // Get page permit as proof for consent
 86→        let page_permit = match state.butler.pages().get(page_id) {
 87→            Ok(Some(data)) => match data.get_permit() {
 88→                Some(permit) => permit.clone(),
 89→                None => {
 90→                    warn!("No page permit for page={}, sending consent without proof", page_id);
 91→                    return String::new();
 92→                }
 93→            },
 94→            _ => {
 95→                warn!("Failed to get page data for consent: page={}", page_id);
 96→                return String::new();
 97→            }
 98→        };
 99→
100→        let full_layer_name = format!("{}/{}", page_id, layer_name);
101→        match gurkha::issue_sync_layer_consent(
102→            &signing_key,
103→            &peer_did,
104→            page_id,
105→            &full_layer_name,
106→            &page_permit,
107→            DEFAULT_LAYER_CONSENT_TEMPLATE,
108→        ).await {
109→            Ok((token, _cid)) => {
110→                debug!("Issued layer consent for layer={}", layer_name);
111→                token
112→            }
113→            Err(e) => {
114→                warn!("Failed to issue layer consent: {}", e);
115→                String::new()
116→            }
117→        }
118→    }
119→
120→    /// Subscribe to dynamic layers on a peer (triggered by Coordinator)
121→    ///
122→    /// **Context**: Scribe emitted SyncEvent::SubscribeLayers, Coordinator forwarded here
123→    /// **We do**: Issue consent permits, send LayerSubscribe for each layer
124→    #[instrument(skip(self, state), fields(node = %self.node_id, page_id = %page_id))]
125→    pub(in crate::peer_actor) async fn subscribe_to_layers(
126→        &self,
127→        page_id: &str,
128→        layers: &[String],
129→        state: &mut PeerActorState<C>,
130→    ) {
131→        if layers.is_empty() {
132→            return;
133→        }
134→
135→        info!(
136→            page_id = %page_id,
137→            count = layers.len(),
138→            "Subscribing to {} layers via LayerSubscribe",
139→            layers.len()
140→        );
141→
142→        for layer_name in layers {
143→            let consent_permit = self.issue_layer_consent(page_id, layer_name, state).await;
144→            let request_id = uuid::Uuid::new_v4().to_string();
145→            let msg = Message::LayerSubscribe(LayerSubscribeMsg {
146→                request_id,
147→                page_id: page_id.to_string(),
148→                layer_name: layer_name.clone(),
149→                consent_permit,
150→            });
151→            self.send_message(&msg, state).await;
152→            debug!(page_id = %page_id, layer = %layer_name, "Sent LayerSubscribe");
153→        }
154→    }
155→
156→    /// Detect __sync_meta updates and send LayerSubscribe for unsynced entries
157→    ///
158→    /// **Context**: PeerActor applied a SyncOffer for a __sync_meta layer
159→    /// **We do**: Query Scribe for unsynced entries, issue consent, send LayerSubscribe for each
160→    #[instrument(skip(self, state), fields(node = %self.node_id, page_id = %page_id))]
161→    pub(in crate::peer_actor) async fn check_sync_meta_and_subscribe(
162→        &self,
163→        page_id: &str,
164→        state: &mut PeerActorState<C>,
165→    ) {
166→        let scribe = match state.butler.open_page(page_id).await {
167→            Ok(s) => s,
168→            Err(e) => {
169→                error!("Failed to open page {} for sync_meta check: {}", page_id, e);
170→                return;
171→            }
172→        };
173→
174→        // Query Scribe for unsynced __sync_meta entries
175→        let (reply_tx, reply_rx) = tokio::sync::oneshot::channel();
176→        if let Err(e) = scribe.cast(ScribeMessage::GetUnsyncedSyncMeta { reply: reply_tx }) {
177→            error!("Failed to query unsynced sync_meta: {}", e);
178→            return;
179→        }
180→
181→        let unsynced = match reply_rx.await {
182→            Ok(entries) => entries,
183→            Err(_) => {
184→                error!("GetUnsyncedSyncMeta reply channel dropped");
185→                return;
186→            }
187→        };
188→
189→        if unsynced.is_empty() {
190→            debug!("No unsynced __sync_meta entries for page={}", page_id);
191→            return;
192→        }
193→
194→        // Delegate to subscribe_to_layers which handles consent + sending
195→        self.subscribe_to_layers(page_id, &unsynced, state).await;
196→    }
197→
198→    /// Handle incoming LayerSubscribe from peer
199→    ///
200→    /// **Context**: Peer discovered a layer in __sync_meta, requests data + permit
201→    /// **We do**: Store consent permit, delegate to Scribe for permit + snapshot, encrypt, respond
202→    #[instrument(skip(self, state, consent_permit), fields(page_id = %page_id, layer = %layer_name))]
203→    pub(in crate::peer_actor) async fn on_layer_subscribe(
204→        &self,
205→        request_id: &str,
206→        page_id: &str,
207→        layer_name: &str,
208→        consent_permit: &str,
209→        state: &mut PeerActorState<C>,
210→    ) {
211→        let (peer_did, _) = match require_auth(&state.state) {
212→            Ok(info) => (info.0.to_string(), info.1.to_string()),
213→            Err(_) => {
214→                warn!("LayerSubscribe from unauthenticated peer: {}", self.node_id);
215→                return;
216→            }
217→        };
218→
219→        info!(
220→            "LayerSubscribe: page={} layer={} from peer={}",
221→            page_id, layer_name, peer_did
222→        );
223→
224→        // Store consent permit if provided
225→        if !consent_permit.is_empty() {
226→            let full_layer_name = format!("{}/{}", page_id, layer_name);
227→            if let Err(e) = state.butler.permits().store_viewer_layer_consent(
228→                &peer_did, page_id, &full_layer_name, consent_permit,
229→            ) {
230→                warn!("Failed to store viewer layer consent: {}", e);
231→                // Non-fatal — continue processing
232→            } else {
233→                debug!("Stored viewer layer consent for peer={} layer={}", peer_did, layer_name);
234→            }
235→        }
236→
237→        // Get Scribe for this page
238→        let scribe = match state.page_subscriptions.get(page_id) {
239→            Some(sub) => sub.scribe.clone(),
240→            None => {
241→                warn!("LayerSubscribe: no page subscription for page={}", page_id);
242→                self.send_layer_subscribe_reject(request_id, page_id, layer_name, "page not subscribed", state).await;
243→                return;
244→            }
245→        };
246→
247→        // Delegate to Scribe: issues permit, adds subscriber, exports snapshot
248→        let (reply_tx, reply_rx) = tokio::sync::oneshot::channel();
249→        if let Err(e) = scribe.cast(ScribeMessage::HandleLayerSubscribe {
250→            layer_name: layer_name.to_string(),
251→            peer_did: peer_did.clone(),
252→            reply: reply_tx,
253→        }) {
254→            error!("Failed to send HandleLayerSubscribe to Scribe: {}", e);
255→            self.send_layer_subscribe_reject(request_id, page_id, layer_name, "internal error", state).await;
256→            return;
257→        }
258→
259→        let (snapshot_data, state_vector, layer_permit) = match reply_rx.await {
260→            Ok(Ok(result)) => {
261→                Self::emit_layer_subscribe_protocol_capture(
262→                    &state.capture_tx, "incoming", page_id, layer_name, &peer_did, "ok", None,
263→                );
264→                result
265→            }
266→            Ok(Err(e)) => {
267→                warn!("HandleLayerSubscribe error for layer={}: {}", layer_name, e);
268→                Self::emit_layer_subscribe_protocol_capture(
269→                    &state.capture_tx, "incoming", page_id, layer_name, &peer_did, "err", Some(&e),
270→                );
271→                self.send_layer_subscribe_reject(request_id, page_id, layer_name, &e, state).await;
272→                return;
273→            }
274→            Err(_) => {
275→                error!("HandleLayerSubscribe reply dropped for layer={}", layer_name);
276→                Self::emit_layer_subscribe_protocol_capture(
277→                    &state.capture_tx, "incoming", page_id, layer_name, &peer_did, "err", Some("reply dropped"),
278→                );
279→                self.send_layer_subscribe_reject(request_id, page_id, layer_name, "internal error", state).await;
280→                return;
281→            }
282→        };
283→
284→        // Encrypt snapshot for transfer
285→        let peer_encryption_key = match state.peer_encryption_key {
286→            Some(key) => key,
287→            None => {
288→                warn!("Cannot send LayerSubscribeAck: peer encryption key not set");
289→                self.send_layer_subscribe_reject(request_id, page_id, layer_name, "no encryption key", state).await;
290→                return;
291→            }
292→        };
293→
294→        let (ephemeral_public, encrypted_data) = match herald::encrypt_for_transfer(
295→            &peer_encryption_key,
296→            &snapshot_data,
297→        ) {
298→            Ok(result) => result,
299→            Err(e) => {
300→                error!("Failed to encrypt LayerSubscribeAck data: {}", e);
301→                self.send_layer_subscribe_reject(request_id, page_id, layer_name, "encryption failed", state).await;
302→                return;
303→            }
304→        };
305→
306→        // Ensure peer is a per-layer subscriber for future broadcasts.
307→        // HandleLayerSubscribe attempts this internally, but as a belt-and-suspenders
308→        // we also send an explicit AuthorizeLayerSubscriber from here.
309→        scribe.cast(ScribeMessage::AuthorizeLayerSubscriber {
310→            layer_name: layer_name.to_string(),
311→            subscriber_did: peer_did.clone(),
312→        }).ok();
313→
314→        // Mark the entry as synced in the peer's __sync_meta on the node
315→        if let Some(sub) = state.page_subscriptions.get(page_id) {
316→            let meta_layer = format!("__sync_meta:{}", peer_did);
317→            let _ = sub.scribe.cast(ScribeMessage::UpdateFromJson {
318→                layer_name: meta_layer,
319→                path: layer_name.to_string(),
320→                value: serde_json::json!(true),
321→                reply: None,
322→            });
323→        }
324→
325→        let msg = Message::LayerSubscribeAck(LayerSubscribeAckMsg {
326→            request_id: request_id.to_string(),
327→            page_id: page_id.to_string(),
328→            layer_name: layer_name.to_string(),
329→            accepted: true,
330→            reason: None,
331→            data: encrypted_data,
332→            state_vector,
333→            ephemeral_public,
334→            layer_permit,
335→        });
336→
337→        self.send_message(&msg, state).await;
338→        info!("Sent LayerSubscribeAck for page={} layer={} to peer={}", page_id, layer_name, peer_did);
339→    }
340→
341→    /// Send a rejected LayerSubscribeAck
342→    async fn send_layer_subscribe_reject(
343→        &self,
344→        request_id: &str,
345→        page_id: &str,
346→        layer_name: &str,
347→        reason: &str,
348→        state: &PeerActorState<C>,
349→    ) {
350→        let msg = Message::LayerSubscribeAck(LayerSubscribeAckMsg {
351→            request_id: request_id.to_string(),
352→            page_id: page_id.to_string(),
353→            layer_name: layer_name.to_string(),
354→            accepted: false,
355→            reason: Some(reason.to_string()),
356→            data: Vec::new(),
357→            state_vector: Vec::new(),
358→            ephemeral_public: [0u8; 32],
359→            layer_permit: String::new(),
360→        });
361→        self.send_message(&msg, state).await;
362→    }
363→
364→    /// Handle incoming LayerSubscribeAck from peer
365→    ///
366→    /// **Context**: Peer processed our LayerSubscribe, sent data + permit
367→    /// **Permit-driven**: Detects permit type to determine handling:
368→    ///   - `layer_authority` → We're the node, creator sent authority. Store + fan out.
369→    ///   - `layer_permit` → We're the user, node sent access permit. Store + apply.
370→    #[instrument(skip(self, state, data, state_vector, ephemeral_public, layer_permit), fields(page_id = %page_id, layer = %layer_name))]
371→    pub(in crate::peer_actor) async fn on_layer_subscribe_ack(
372→        &self,
373→        _request_id: &str,
374→        page_id: &str,
375→        layer_name: &str,
376→        accepted: bool,
377→        reason: Option<&str>,
378→        data: &[u8],
379→        state_vector: &[u8],
380→        ephemeral_public: &[u8; 32],
381→        layer_permit: &str,
382→        state: &mut PeerActorState<C>,
383→    ) {
384→        let (peer_did, _) = match require_auth(&state.state) {
385→            Ok(info) => (info.0.to_string(), info.1.to_string()),
386→            Err(_) => {
387→                warn!("LayerSubscribeAck from unauthenticated peer: {}", self.node_id);
388→                return;
389→            }
390→        };
391→
392→        if !accepted {
393→            let reject_reason = reason.unwrap_or("unknown");
394→            warn!(
395→                "LayerSubscribeAck rejected for page={} layer={}: {}",
396→                page_id, layer_name, reject_reason
397→            );
398→            Self::emit_layer_subscribe_protocol_capture(
399→                &state.capture_tx, "ack_rejected", page_id, layer_name, &peer_did, "err", Some(reject_reason),
400→            );
401→            return;
402→        }
403→
404→        info!(
405→            "LayerSubscribeAck: page={} layer={} from peer={} data_len={}",
406→            page_id, layer_name, peer_did, data.len()
407→        );
408→
409→        // Decrypt data
410→        let our_secret = match state.butler.encryption_key().await {
411→            Ok(key) => key,
412→            Err(e) => {
413→                error!("Failed to get encryption key for LayerSubscribeAck: {}", e);
414→                return;
415→            }
416→        };
417→
418→        let decrypted_data = match herald::decrypt_from_transfer(&our_secret, ephemeral_public, data) {
419→            Ok(plaintext) => plaintext,
420→            Err(e) => {
421→                error!("Failed to decrypt LayerSubscribeAck data: {}", e);
422→                return;
423→            }
424→        };
425→
426→        // Detect permit type to determine handling path
427→        let is_authority = gurkha::Permit::from_token(layer_permit)
428→            .ok()
429→            .and_then(|p| p.get_fact("token_type").cloned())
430→            .and_then(|v| v.as_str().map(|s| s.to_string()))
431→            .map(|t| t == "layer_authority")
432→            .unwrap_or(false);
433→
434→        if is_authority {
435→            self.handle_authority_ack(page_id, layer_name, &peer_did, layer_permit, &decrypted_data, state_vector, state).await;
436→        } else {
437→            self.handle_layer_permit_ack(page_id, layer_name, &peer_did, layer_permit, &decrypted_data, state).await;
438→        }
439→    }
440→
441→    /// Handle LayerSubscribeAck containing a layer_authority permit (node received from creator)
442→    ///
443→    /// **Context**: We're the node, a creator responded with authority for a dynamic layer
444→    /// **We do**: Send StoreLayerAuthority to Scribe (stores authority, applies data, fans out)
445→    #[instrument(skip(self, state, data, state_vector), fields(page_id = %page_id, layer = %layer_name, creator = %creator_did))]
446→    async fn handle_authority_ack(
447→        &self,
448→        page_id: &str,
449→        layer_name: &str,
450→        creator_did: &str,
451→        authority_token: &str,
452→        data: &[u8],
453→        state_vector: &[u8],
454→        state: &mut PeerActorState<C>,
455→    ) {
456→        info!("Received layer_authority for layer={} from creator={}", layer_name, creator_did);
457→
458→        let scribe = match state.page_subscriptions.get(page_id) {
459→            Some(sub) => sub.scribe.clone(),
460→            None => {
461→                warn!("No page subscription for page={}, cannot store authority", page_id);
462→                return;
463→            }
464→        };
465→
466→        // Delegate to Scribe: store authority, apply data, fan out to authorized users
467→        if let Err(e) = scribe.cast(ScribeMessage::StoreLayerAuthority {
468→            layer_name: layer_name.to_string(),
469→            creator_did: creator_did.to_string(),
470→            authority_token: authority_token.to_string(),
471→            layer_data: data.to_vec(),
472→            state_vector: state_vector.to_vec(),
473→        }) {
474→            error!("Failed to send StoreLayerAuthority to Scribe: {}", e);
475→            return;
476→        }
477→
478→        // Authorize creator as subscriber for bidirectional sync
479→        scribe.cast(ScribeMessage::AuthorizeLayerSubscriber {
480→            layer_name: layer_name.to_string(),
481→            subscriber_did: creator_did.to_string(),
482→        }).ok();
483→
484→        // Mark creator's __sync_meta entry as synced
485→        let meta_layer = format!("__sync_meta:{}", creator_did);
486→        let _ = scribe.cast(ScribeMessage::UpdateFromJson {
487→            layer_name: meta_layer,
488→            path: layer_name.to_string(),
489→            value: serde_json::json!(true),
490→            reply: None,
491→        });
492→
493→        info!("Stored authority and initiated fanout for layer={}", layer_name);
494→    }
495→
496→    /// Handle LayerSubscribeAck containing a layer_permit (user received from node)
497→    ///
498→    /// **Context**: We're the user, node responded with access permit for a dynamic layer
499→    /// **We do**: Store permit, apply data to Scribe, authorize node, mark synced
500→    #[instrument(skip(self, state, data), fields(page_id = %page_id, layer = %layer_name, node = %node_did))]
501→    async fn handle_layer_permit_ack(
502→        &self,
503→        page_id: &str,
504→        layer_name: &str,
505→        node_did: &str,
506→        layer_permit: &str,
507→        data: &[u8],
508→        state: &mut PeerActorState<C>,
509→    ) {
510→        info!("Received layer_permit for layer={} from node={}", layer_name, node_did);
511→
512→        // Store layer permit
513→        let full_layer_name = format!("{}/{}", page_id, layer_name);
514→        let our_did = match state.butler.get_identity().await {
515→            Ok(identity) => identity.did().to_string(),
516→            Err(e) => {
517→                error!("Failed to get our identity: {}", e);
518→                return;
519→            }
520→        };
521→
522→        if let Err(e) = state.butler.permits().store_layer_permit(
523→            page_id, &our_did, &full_layer_name, layer_permit,
524→        ) {
525→            error!("Failed to store layer permit: {}", e);
526→            return;
527→        }
528→
529→        info!("Stored layer permit for layer={}", full_layer_name);
530→
531→        // Apply data to Scribe
532→        if let Some(subscription) = state.page_subscriptions.get(page_id) {
533→            let (reply_tx, reply_rx) = tokio::sync::oneshot::channel();
534→            if let Err(e) = subscription.scribe.cast(ScribeMessage::ApplyUpdateWithResult {
535→                layer_name: layer_name.to_string(),
536→                update: data.to_vec(),
537→                from_peer: Some((node_did.to_string(), self.node_id.to_string())),
538→                permit: Some(layer_permit.to_string()),
539→                reply: reply_tx,
540→            }) {
541→                error!("Failed to send ApplyUpdate for LayerSubscribeAck: {}", e);
542→                return;
543→            }
544→
545→            match reply_rx.await {
546→                Ok(Ok(())) => {
547→                    info!("Applied LayerSubscribeAck data for layer={}", layer_name);
548→                }
549→                Ok(Err(e)) => {
550→                    warn!("Scribe rejected LayerSubscribeAck data for layer={}: {}", layer_name, e);
551→                }
552→                Err(_) => {
553→                    error!("ApplyUpdate reply dropped for layer={}", layer_name);
554→                    return;
555→                }
556→            }
557→
558→            // Authorize node as subscriber for bidirectional sync
559→            subscription.scribe.cast(ScribeMessage::AuthorizeLayerSubscriber {
560→                layer_name: layer_name.to_string(),
561→                subscriber_did: node_did.to_string(),
562→            }).ok();
563→            info!("Authorized node {} on layer={}", node_did, layer_name);
564→
565→            // Mark __sync_meta entry as synced
566→            subscription.scribe.cast(ScribeMessage::MarkSyncMetaSynced {
567→                layer_name: layer_name.to_string(),
568→            }).ok();
569→        } else {
570→            warn!("No page subscription for page={}, cannot apply LayerSubscribeAck", page_id);
571→        }
572→    }
573→}
