 26→    /// Store a layer permit for a peer (additive).
 27→    ///
 28→    /// **Context**: Node detected new dynamic layer, issued permit for peer.
 29→    #[instrument(skip_all)]
 30→    pub fn store_layer_permit(
 31→        &self,
 32→        page_id: &str,
 33→        user_did: &str,
 34→        layer_name: &str,
 35→        permit_token: &str,
 36→    ) -> Result<()> {
 37→        let key = format!("{}/{}/{}", page_id, user_did, layer_name);
 38→        let write_txn = self.db.begin_write()?;
 39→        {
 40→            let mut table = write_txn.open_table(LAYER_PERMITS)?;
 41→            table.insert(key.as_str(), permit_token)?;
 42→        }
 43→        write_txn.commit()?;
 44→        Ok(())
 45→    }
