277→            };
278→            let record_bytes = serde_json::to_vec(&record)
279→                .map_err(|e| crate::error::ButlerError::Serialization(e.to_string()))?;
280→            table.insert(key.as_str(), record_bytes.as_slice())?;
281→        }
