245→    // ── Layer Authority Permit Operations ─────────────────────────────────
246→    // Key: {page_id}/{audience}/{layer_name} -> JSON {version, permit}
247→
248→    /// Store latest layer authority permit for page/layer/audience.
249→    ///
250→    /// Older or equal versions are ignored.
251→    #[instrument(skip_all)]
252→    pub fn store_layer_authority_permit(
253→        &self,
254→        page_id: &str,
255→        layer_name: &str,
256→        audience: &str,
257→        version: u64,
258→        permit_token: &str,
259→    ) -> Result<()> {
260→        let key = format!("{}/{}/{}", page_id, audience, layer_name);
261→        let write_txn = self.db.begin_write()?;
262→        {
263→            let mut table = write_txn.open_table(LAYER_AUTHORITY_PERMITS)?;
264→
265→            if let Some(existing) = table.get(key.as_str())? {
266→                if let Ok(record) = serde_json::from_slice::<LayerAuthorityRecord>(existing.value())
267→                {
268→                    if record.version >= version {
269→                        return Ok(());
270→                    }
271→                }
272→            }
273→
274→            let record = LayerAuthorityRecord {
275→                version,
276→                permit: permit_token.to_string(),
277→            };
278→            let record_bytes = serde_json::to_vec(&record)
279→                .map_err(|e| crate::error::ButlerError::Serialization(e.to_string()))?;
280→            table.insert(key.as_str(), record_bytes.as_slice())?;
281→        }
282→        write_txn.commit()?;
283→        Ok(())
284→    }
285→
286→    /// Get latest layer authority permit for page/layer/audience.
287→    #[instrument(skip_all)]
288→    pub fn get_layer_authority_permit(
289→        &self,
290→        page_id: &str,
291→        layer_name: &str,
292→        audience: &str,
293→    ) -> Result<Option<(u64, String)>> {
294→        let key = format!("{}/{}/{}", page_id, audience, layer_name);
295→        let read_txn = self.db.begin_read()?;
296→        let table = read_txn.open_table(LAYER_AUTHORITY_PERMITS)?;
297→
298→        let Some(guard) = table.get(key.as_str())? else {
299→            return Ok(None);
300→        };
301→
302→        let record = serde_json::from_slice::<LayerAuthorityRecord>(guard.value())
303→            .map_err(|e| crate::error::ButlerError::Serialization(e.to_string()))?;
304→        Ok(Some((record.version, record.permit)))
305→    }
