308→    ///
309→    /// Returns (layer_name, version, permit_token).
310→    #[instrument(skip_all)]
311→    pub fn list_layer_authority_permits_for_audience(
312→        &self,
313→        page_id: &str,
314→        audience: &str,
315→    ) -> Result<Vec<(String, u64, String)>> {
316→        let prefix = format!("{}/{}/", page_id, audience);
317→        let read_txn = self.db.begin_read()?;
318→        let table = read_txn.open_table(LAYER_AUTHORITY_PERMITS)?;
319→
320→        let mut permits = Vec::new();
321→        for result in table.range(prefix.as_str()..)? {
322→            let (key, value) = result?;
323→            let key_str = key.value();
324→
325→            if !key_str.starts_with(&prefix) {
326→                break;
327→            }
328→
329→            let Some(layer_name) = key_str.strip_prefix(&prefix) else {
330→                continue;
331→            };
332→
333→            let record = serde_json::from_slice::<LayerAuthorityRecord>(value.value())
334→                .map_err(|e| crate::error::ButlerError::Serialization(e.to_string()))?;
335→            permits.push((layer_name.to_string(), record.version, record.permit));
336→        }
337→
338→        Ok(permits)
339→    }
340→    /// Get stored authority for a layer regardless of audience (creator).
341→    ///
342→    /// **Context**: Node needs to find ANY stored authority for a given layer.
343→    /// Scans all authority permits for the page. Key format: `{page_id}/{audience}/{layer_name}`.
344→    /// **Returns**: (creator_did, version, authority_token) if found.
345→    #[instrument(skip_all)]
346→    pub fn get_authority_for_layer(
347→        &self,
348→        page_id: &str,
349→        layer_name: &str,
350→    ) -> Result<Option<(String, u64, String)>> {
351→        let page_prefix = format!("{}/", page_id);
352→        let read_txn = self.db.begin_read()?;
353→        let table = read_txn.open_table(LAYER_AUTHORITY_PERMITS)?;
354→
355→        for result in table.range(page_prefix.as_str()..)? {
356→            let (key, value) = result?;
357→            let key_str = key.value();
358→
359→            if !key_str.starts_with(&page_prefix) {
360→                break;
361→            }
362→
363→            // Key format: {page_id}/{audience}/{layer_name}
364→            // We need to find entries where the suffix after {page_id}/{audience}/ matches layer_name
365→            let rest = &key_str[page_prefix.len()..];
366→            // rest = {audience}/{layer_name}
367→            // Find the first '/' after audience (audience is a DID, contains colons but no slashes until the layer_name part)
368→            // Actually DIDs don't contain '/' but layer_name can have '/'.
369→            // The audience is always a DID like "did:key:..." which doesn't contain '/'.
370→            // So the first '/' separates audience from layer_name.
371→            if let Some(slash_pos) = rest.find('/') {
372→                let audience = &rest[..slash_pos];
