188→/// Send initial state to a newly subscribed peer for layers they have access to
189→#[instrument(skip_all, fields(page_id = %state.page_id, user_did = %user_did))]
190→async fn send_initial_state_to_subscriber(
191→    state: &ScribeState,
192→    user_did: &str,
193→    device_id: &str,
194→    broadcast_tx: &mpsc::Sender<BroadcastPayload>,
195→) {
196→    let peer_vectors = match state.vector_storage.load_vectors(user_did, device_id) {
197→        Ok(Some(v)) => v.into_iter()
198→            .map(|(k, v)| (normalize_layer_name(&k, &state.page_id), v))
199→            .collect(),
200→        Ok(None) => HashMap::new(),
201→        Err(_) => HashMap::new(),
202→    };
203→
204→    for (layer_name, unit) in &state.units {
205→        // Only send to layers where subscriber was added
206→        if !unit.can_push_to(user_did) {
207→            continue;
208→        }
209→
210→        let layer = unit.layer();
211→
212→        let data = if let Some(their_vector) = peer_vectors.get(layer_name) {
213→            if their_vector.is_empty() {
214→                layer.export_snapshot()
215→            } else {
216→                match layer.export_updates(their_vector) {
217→                    Ok(updates) if updates.is_empty() => {
218→                        debug!(user_did = %user_did, layer = %layer_name, "No new updates");
219→                        continue;
220→                    }
221→                    Ok(updates) => updates,
222→                    Err(e) => {
223→                        warn!(error = %e, layer = %layer_name, "Failed incremental export, using snapshot");
224→                        layer.export_snapshot()
225→                    }
226→                }
227→            }
228→        } else {
229→            layer.export_snapshot()
230→        };
231→
232→        let state_vector = layer.version_vector();
233→
234→        if data.is_empty() || state_vector.len() <= 1 {
235→            debug!(user_did = %user_did, layer = %layer_name, "Skipping empty layer");
236→            continue;
237→        }
238→
239→        let payload = BroadcastPayload {
240→            page_id: state.page_id.clone(),
241→            layer_name: layer_name.clone(),
242→            layer_type: domains::LayerType::from_layer_name(layer_name),
243→            update: data,
244→            state_vector,
245→        };
246→
247→        if let Err(e) = broadcast_tx.try_send(payload) {
248→            warn!(user_did = %user_did, layer = %layer_name, error = %e, "Failed to send initial state");
249→        } else {
250→            debug!(user_did = %user_did, layer = %layer_name, "Sent initial state");
251→        }
252→    }
253→}
254→
255→/// Bootstrap __sync_meta for a newly subscribed peer (node-side)
256→///
257→/// **Context**: After a peer subscribes, the node creates their __sync_meta layer,
258→/// populates it with static layer entries, adds existing dynamic layer entries
259→/// for late joiners, and subscribes the peer to their __sync_meta layer.
260→#[instrument(skip(state, broadcast_tx), fields(page_id = %state.page_id, peer_did = %peer_did))]
261→fn bootstrap_sync_meta(
262→    state: &mut ScribeState,
263→    peer_did: &str,
264→    peer_permit: &gurkha::Permit,
265→    broadcast_tx: &mpsc::Sender<BroadcastPayload>,
266→) {
267→    use super::sync_meta;
268→
269→    // 1. Create __sync_meta:{peer_did} layer
270→    let meta_layer_name = sync_meta::ensure_sync_meta_layer(state, peer_did);
271→
272→    // 2. Populate with static layer entries
273→    let is_owner = peer_permit.relationship() == Some("owner");
274→    sync_meta::populate_static_layers(state, peer_did, peer_permit, is_owner);
275→
276→    // 3. Populate dynamic layers for late joiners
277→    sync_meta::populate_dynamic_layers_for_late_joiner(state, peer_did);
278→
279→    // 4. Subscribe the peer to their __sync_meta layer so it syncs to them
280→    if let Some(unit) = state.units.get(&meta_layer_name) {
281→        let caps = Capabilities { read: true, write: true, sync: true };
282→        unit.add_subscriber(peer_did.to_string(), caps, broadcast_tx.clone());
283→        info!(
284→            layer = %meta_layer_name,
285→            peer_did = %peer_did,
286→            "Subscribed peer to their __sync_meta layer"
287→        );
288→    }
289→}
