        .cast(ScribeMessage::EnsureLoroMap {
            layer_name: layer_name.to_string(),
            reply: tx,
        })
        .map_err(|e| format!("Failed to ensure map: {}", e))?;
    rpc(rx)
}

fn create_derived_layer(&self, target_layer: &str) -> Result<(), String> {
